<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import { ElButton } from 'element-plus'
import { evidenceGet } from '../api/evidence'
import { statuses } from '../types/workbench'
import type { ReliabilityView, SavedRule } from '../types/reliability'
import InfoHint from './InfoHint.vue'

const props = defineProps<{ runId: string; authorization: string; executionId?: string; revision: string }>()
const emit = defineEmits<{ execution: [id: string]; locate: [id: string]; snapshot: [id: string]; assertion: [execution: string, id: number, version: string]; diagnosis: [id: string]; semantic: [id: string] }>()
const data = shallowRef<ReliabilityView>(), busy = ref(false), error = ref(''), selected = ref(''), cohortId = ref(''), dimensionId = ref(''), attentionOnly = ref(false)
const story = ref<HTMLElement>()
let generation = 0, controller: AbortController | undefined
const assessment: Record<string,string> = { passed:'规则通过',failed:'规则未通过',inconclusive:'证据不足',insufficient:'证据不足',error:'评价错误',platform_error:'执行异常',pending:'尚未判定',excluded:'未计入业务判定',not_evaluated:'尚无保存判定',na:'不适用' }
const outcomes: Record<string,string> = { fulfilled:'任务已达成',not_fulfilled:'任务未达成',safely_degraded:'安全降级',unknown:'任务结果未知' }
const modes: Record<string,string> = { real_provider:'真实模型',offline_test_double:'受控离线',unrecorded:'来源未记录' }
const splits: Record<string,string> = { dev:'开发集',development:'开发集',holdout:'保留集',calibration:'校准集' }
const faultStates: Record<string,string> = { injected:'实际已触发',not_triggered:'配置了故障，实际未触发',unconfirmed:'故障触发情况尚不能确认',control:'无故障配置' }
const current = computed(() => data.value?.executions.find(e => e.execution_id === selected.value))
const cohort = computed(() => data.value?.cohorts.find(c => c.id === cohortId.value))
const dimension = computed(() => cohort.value?.dimensions.find(d => d.id === dimensionId.value))
const visible = computed(() => data.value?.executions.filter(e => !attentionOnly.value || e.assessment !== 'passed') ?? [])
const concerns = computed(() => current.value?.saved_rules.filter(r => ['failed','error','inconclusive'].includes(r.verdict)) ?? [])
const modeLabel = (value: string | null) => modes[value ?? 'unrecorded'] ?? '来源待核对'
const count = (values: Record<string,number>, key: string) => values[key] ?? 0
function expectation(value: Record<string,unknown>) {
  switch(value.type) {
    case 'booking_count': return `有效预约 ${value.equals} 笔`
    case 'booking_matches': return `预约条件：${[value.date,value.room_code,value.attendees ? `${value.attendees}人` : ''].filter(Boolean).join(' · ')}`
    case 'no_booking_on': return `${value.date} 不产生有效预约`
    case 'tool_calls': return `${value.tool} 调用 ${value.min_calls ?? 1}—${value.max_calls ?? 20} 次`
    case 'state_matches': return `最终字段：${Object.entries(value.fields as Record<string,unknown> ?? {}).map(([k,v]) => `${k}=${v ?? '空'}`).join(' · ')}`
    default: return ({confirmation_binding:'确认绑定当前草稿',original_request_recovery:'未知提交使用原请求查证',business_consistent:'业务声明与SQL一致',unique_bookings:'有效预约不重复',reply_booking_consistent:'预约回复与SQL一致',reply_literals:'检查声明的回复片段'} as Record<string,string>)[String(value.type)] ?? String(value.type)
  }
}
async function load() {
  const ticket = ++generation, run = props.runId
  controller?.abort(); controller = new AbortController(); busy.value = true; error.value = ''; data.value = undefined
  try {
    const value = await evidenceGet<ReliabilityView>(`/runs/${run}/reliability`, props.authorization, controller.signal)
    if(ticket !== generation) return
    if(value.run_id !== run || value.schema !== 'reliability-view-v1' || !value.complete_read) throw new Error('摘要归属或读取范围无法核对。')
    data.value = value
    selected.value = value.executions.find(e => e.execution_id === props.executionId)?.execution_id ?? value.executions.find(e => e.assessment !== 'passed')?.execution_id ?? value.executions[0]?.execution_id ?? ''
    cohortId.value = value.cohorts.find(c => c.execution_ids.includes(selected.value))?.id ?? value.cohorts[0]?.id ?? ''
    dimensionId.value = ''
  } catch(e) { if(ticket === generation) error.value = (e as Error).message }
  finally { if(ticket === generation) busy.value = false }
}
function choose(id: string) { selected.value = id; emit('execution',id) }
function showRule(row: SavedRule) { if(current.value) emit('assertion',current.value.execution_id,row.id,row.evaluator_version) }
async function inspectSample(sample: {execution_id:string;assertion_ids:number[];evaluator_version:string|null}) {
  choose(sample.execution_id)
  if(sample.assertion_ids.length && sample.evaluator_version) emit('assertion',sample.execution_id,sample.assertion_ids[0]!,sample.evaluator_version)
  else { await nextTick(); story.value?.focus(); story.value?.scrollIntoView({block:'start'}) }
}
watch(() => [props.runId,props.authorization,props.revision], () => { void load() }, { immediate:true })
watch(() => props.executionId, value => { if(value && data.value?.executions.some(e => e.execution_id === value)) selected.value = value })
watch(cohortId, () => { dimensionId.value = '' })
watch(attentionOnly, value => { if(value && current.value?.assessment === 'passed' && visible.value[0]) choose(visible.value[0].execution_id) })
onBeforeUnmount(() => { generation++; controller?.abort() })
</script>

<template>
  <section class="reliability-view" aria-label="可靠性结果概览" :aria-busy="busy">
    <header class="reliability-toolbar"><h2>结果概览</h2><ElButton :disabled="busy" @click="load">刷新摘要</ElButton></header>
    <p v-if="busy" role="status">正在核对已保存的判定与完整执行证据…</p>
    <p v-else-if="error" role="alert" class="reliability-error">{{ error }}</p>
    <template v-else-if="data">
      <div class="reliability-run-facts"><span>历史记录</span><span>版本 {{ data.target_version_id }}</span><span>{{ data.conditions.model ?? '模型未记录' }}</span><span>计划 {{ data.planned_executions }} · 已记录 {{ data.executions.length }} 次执行</span><span>{{ data.event_count }} 条持久事件</span><span>采集 {{ new Date(data.observed_at).toLocaleTimeString('zh-CN',{hour12:false}) }}</span><InfoHint label="摘要统计范围" :text="data.boundary" /></div>
      <div class="reliability-statuses" aria-label="平台执行状态"><span v-for="(n,status) in data.execution_status_counts" :key="status">{{ statuses[status] ?? status }} <strong>{{ n }}</strong></span></div>
      <div class="reliability-workspace">
        <aside class="reliability-executions" aria-label="摘要执行列表"><header><strong>执行</strong><button type="button" :aria-pressed="attentionOnly" @click="attentionOnly = !attentionOnly">{{ attentionOnly ? '查看全部' : '只看需关注' }}</button></header><button v-for="item in visible" :key="item.execution_id" type="button" :aria-pressed="selected === item.execution_id" :data-assessment="item.assessment" @click="choose(item.execution_id)"><strong>{{ item.case_key ?? item.execution_id.slice(0,8) }}</strong><span>{{ assessment[item.assessment] ?? item.assessment }}</span><small>{{ modeLabel(item.gateway_mode) }} · {{ splits[item.dataset_split] ?? item.dataset_split }} · 重复{{ item.repeat_no }}</small></button><p v-if="!visible.length">当前筛选下没有执行。</p></aside>
        <article v-if="current" ref="story" class="reliability-story" aria-label="执行证据摘要" tabindex="-1">
          <header><div><h3>{{ current.case_key ?? '执行记录' }}</h3><span>{{ statuses[current.status] ?? current.status }} · {{ current.execution_id.slice(0,8) }}</span></div><strong class="reliability-assessment" :data-assessment="current.assessment">{{ assessment[current.assessment] ?? current.assessment }}</strong></header>
          <section><h4><b>01</b> 测试预期</h4><ul><li v-for="(spec,i) in current.definitions" :key="i">{{ expectation(spec) }}</li></ul><p v-if="!current.definitions.length">原记录未提供测试预期。</p><details><summary>原始输入与目标</summary><p v-for="(turn,i) in current.turns" :key="i">{{ i + 1 }}. {{ turn.user }}</p><pre>{{ JSON.stringify(current.goal,null,2) ?? '未声明任务目标' }}</pre></details></section>
          <section><h4><b>02</b> 条件与实际故障</h4><div class="reliability-inline"><span>{{ modeLabel(current.gateway_mode) }}</span><span>{{ splits[current.dataset_split] ?? current.dataset_split }}</span><span>时钟 {{ current.reference_clock ?? '未记录' }}</span><span>种子 {{ data.conditions.seed ?? '未记录' }}</span></div><p>{{ faultStates[current.fault.state] ?? current.fault.state }}<template v-if="current.fault.injected"> · {{ current.fault.injected }} 次</template></p><button v-for="id in current.fault.event_ids" :key="id" type="button" class="reliability-link" @click="emit('locate',id)">定位注入事件 {{ id.slice(-8) }}</button><details><summary>冻结知识与故障条件</summary><pre>{{ JSON.stringify({fixture:current.fixture,knowledge:data.conditions.knowledge,fault:data.conditions.fault_profile,limits:data.conditions.limits},null,2) }}</pre></details></section>
          <section><h4><b>03</b> Agent 实际行为</h4><div class="reliability-inline"><span>工具请求 {{ current.behavior.tool_requests }}</span><span>确认事件 {{ current.behavior.confirmation_events }}</span><span>工具错误 {{ current.behavior.tool_errors }}</span><span>模型错误 {{ current.behavior.model_errors }}</span></div><details v-if="current.behavior.reply"><summary>最终回答</summary><p class="reliability-reply">{{ current.behavior.reply }}</p></details><ElButton size="small" @click="emit('diagnosis',current.execution_id)">查看链路诊断</ElButton></section>
          <section><h4><b>04</b> 数据库业务事实</h4><div class="reliability-business"><strong>{{ current.business.active_bookings === null ? '未知' : `${current.business.active_bookings} 笔有效预约` }}</strong><span>{{ outcomes[current.business.task_outcome] ?? '任务结果未知' }}</span><button type="button" class="reliability-link" @click="emit('snapshot',current.execution_id)">核对 SQL 快照</button></div></section>
          <section class="reliability-conclusion"><h4><b>05</b> 判定依据</h4><p v-if="current.assessment === 'pending'">{{ current.status === 'waiting_input' ? '等待本轮输入，尚不能给出业务结论。' : '执行尚未结束，尚不能给出业务结论。' }}</p><p v-else-if="current.assessment === 'platform_error'">执行异常，未计入业务通过或失败。</p><p v-else-if="current.assessment === 'excluded'">此执行未完成业务判定，单独记录。</p><ul v-if="current.evidence_messages.length"><li v-for="message in current.evidence_messages" :key="message">{{ message }}</li></ul><article v-for="row in concerns" :key="row.id" :data-verdict="row.verdict"><strong>{{ row.reason }}</strong><button type="button" class="reliability-link" @click="showRule(row)">核对判定 {{ row.key }}</button></article><p v-if="current.assessment === 'passed'">已保存规则通过，任务结果见上方业务事实。</p><ElButton v-if="current.saved_rules.length" size="small" @click="showRule(current.saved_rules[0]!)">查看全部保存判定</ElButton><small>原判定 {{ assessment[current.rule_verdict] ?? current.rule_verdict }} · {{ current.code_version ?? '评价器未记录' }}</small></section>
          <footer class="reliability-ai"><span>AI 辅助意见：{{ current.ai.records ? `${current.ai.records} 条 · ${assessment[current.ai.verdict] ?? current.ai.verdict}` : '尚无记录' }}</span><ElButton size="small" @click="emit('semantic',current.execution_id)">查看 AI 记录</ElButton></footer>
        </article>
      </div>
      <section class="reliability-coverage" aria-label="可靠性维度覆盖"><header><h2>维度与样本</h2><InfoHint label="维度样本定义" text="同一执行可能覆盖多个维度，各维度不能相加为总样本。只有实际经过相应流程、存在适用保存判定的执行才算覆盖；未经过、仅不适用显示未测试。等待、取消与平台错误单独排除。" /></header>
        <div class="reliability-cohorts" role="group" aria-label="统计分组"><button v-for="item in data.cohorts" :key="item.id" type="button" :aria-pressed="item.id === cohortId" @click="cohortId = item.id">{{ modeLabel(item.gateway_mode) }} · {{ splits[item.dataset_split] ?? item.dataset_split }}<small>{{ item.statistics.planned_executions }} 次执行 · {{ item.statistics.unique_cases }} 个用例修订</small></button></div>
        <template v-if="cohort"><div class="reliability-ratios"><div><span>有效规则通过<InfoHint label="规则通过分母" text="沿用T15：最新规则判定中，执行已结束且证据完整的通过数 /（通过数+未通过数）。证据不足、评价错误、未评价、等待、取消、跳过和平台错误不在分母内，排除项另列。" /></span><strong>{{ cohort.statistics.reliability.numerator }} / {{ cohort.statistics.reliability.denominator }}</strong><small>{{ cohort.evaluator_versions.join('、') || '评价器未记录' }}</small></div><div><span>业务目标达成<InfoHint label="业务目标分母" text="沿用T15：任务达成 /（任务达成+任务未达成）；安全降级与未知单列，不当成目标达成或任务失败。" /></span><strong>{{ cohort.statistics.task_fulfilment.numerator }} / {{ cohort.statistics.task_fulfilment.denominator }}</strong><small>安全降级 {{ count(cohort.statistics.task_outcomes,'safely_degraded') }} · 未知 {{ count(cohort.statistics.task_outcomes,'unknown') }}</small></div><details><summary>分母与排除项</summary><pre>{{ JSON.stringify({rule_outcomes:cohort.statistics.rule_outcomes,task_outcomes:cohort.statistics.task_outcomes},null,2) }}</pre></details></div>
          <div class="reliability-dimensions"><button v-for="item in cohort.dimensions" :key="item.id" type="button" :aria-pressed="dimensionId === item.id" @click="dimensionId = dimensionId === item.id ? '' : item.id"><strong>{{ item.title }}</strong><b>{{ item.denominator ? `${count(item.counts,'passed')} / ${item.denominator}` : count(item.counts,'inconclusive') || count(item.counts,'error') ? '证据不足' : '未测试' }}</b><span>待核对 {{ count(item.counts,'inconclusive') + count(item.counts,'error') }} · 未测试 {{ count(item.counts,'untested') }} · 排除 {{ count(item.counts,'excluded') }}</span></button></div>
          <section v-if="dimension" class="reliability-dimension-detail" aria-label="维度样本依据"><h3>{{ dimension.title }}</h3><p>{{ dimension.definition }}</p><button v-for="sample in dimension.samples" :key="sample.execution_id" type="button" @click="inspectSample(sample)"><span>{{ sample.case_key ?? sample.execution_id.slice(0,8) }}</span><span>{{ ({untested:'未测试',excluded:'已排除',passed:'通过',failed:'未通过',inconclusive:'证据不足',error:'评价错误'} as Record<string,string>)[sample.status] ?? sample.status }}</span><span>查看依据 →</span></button></section>
        </template>
      </section>
    </template>
  </section>
</template>

<style scoped>
.reliability-view{color:var(--ac-text);min-width:0}.reliability-toolbar,.reliability-story>header,.reliability-coverage>header{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:22px 0 14px}.reliability-toolbar h2,.reliability-coverage h2{font-size:18px;margin:0}.reliability-run-facts,.reliability-statuses,.reliability-inline{display:flex;flex-wrap:wrap;gap:8px 20px;font-size:12px;color:var(--ac-muted)}.reliability-statuses{padding:14px 0 20px}.reliability-statuses strong{color:var(--ac-text);margin-left:8px}.reliability-workspace{display:grid;grid-template-columns:260px minmax(0,1fr);border:1px solid var(--ac-border);border-radius:14px;background:var(--ac-surface);overflow:hidden}.reliability-executions{border-right:1px solid var(--ac-border);background:var(--ac-hover);padding:16px;max-height:900px;overflow:auto}.reliability-executions header{display:flex;justify-content:space-between;gap:8px;font-size:13px;padding-bottom:12px}.reliability-executions header button{border:0;background:transparent;color:var(--ac-link);font:inherit;cursor:pointer}.reliability-executions>button{display:grid;gap:7px;width:100%;padding:14px 12px;border:1px solid transparent;border-radius:9px;background:transparent;color:var(--ac-text);text-align:left;cursor:pointer;font:inherit;margin-bottom:6px}.reliability-executions>button[aria-pressed=true]{background:var(--ac-surface);border-color:var(--ac-border);box-shadow:0 2px 6px #00000008}.reliability-executions small,.reliability-executions span{font-size:11px;color:var(--ac-muted)}.reliability-story{padding:24px 30px;min-width:0}.reliability-story>header{margin:0 0 10px;align-items:flex-start}.reliability-story h3{font-size:17px;margin:0 0 7px;overflow-wrap:anywhere}.reliability-story header span{font-size:12px;color:var(--ac-muted)}.reliability-assessment{font-size:13px;white-space:nowrap;color:var(--ac-muted)}[data-assessment=failed]{color:var(--el-color-danger)}[data-assessment=passed]{color:var(--el-color-success)}.reliability-story>section{padding:20px 0;border-top:1px solid var(--ac-border)}.reliability-story h4{font-size:14px;margin:0 0 12px}.reliability-story h4 b{font-size:11px;color:var(--ac-muted);font-weight:500;margin-right:10px;font-variant-numeric:tabular-nums}.reliability-story p,.reliability-story li{font-size:13px;line-height:1.9;margin:5px 0}.reliability-story ul{padding-left:20px;margin:0 0 10px}.reliability-story details{margin:12px 0;font-size:12px;color:var(--ac-muted)}summary{cursor:pointer}.reliability-view pre{max-height:320px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;line-height:1.8;padding:12px;background:var(--ac-hover);border-radius:8px}.reliability-link{border:0;background:transparent;color:var(--ac-link);padding:6px 0;font:inherit;font-size:12px;cursor:pointer;text-align:left}.reliability-business{display:flex;align-items:center;flex-wrap:wrap;gap:12px 24px}.reliability-business strong{font-size:21px;font-variant-numeric:tabular-nums}.reliability-business span{font-size:13px;color:var(--ac-muted)}.reliability-conclusion article{padding:10px 14px;border-left:2px solid var(--el-color-warning);background:var(--ac-hover);margin-bottom:10px;display:grid;font-size:13px;line-height:1.8}.reliability-conclusion small{display:block;margin-top:12px;color:var(--ac-muted);font-size:11px;overflow-wrap:anywhere}.reliability-ai{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid var(--ac-border);padding-top:18px;font-size:12px;color:var(--ac-muted)}.reliability-cohorts{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.reliability-cohorts button{border:1px solid var(--ac-border);border-radius:8px;background:var(--ac-surface);color:var(--ac-text);padding:12px 16px;font:inherit;font-size:13px;cursor:pointer;text-align:left}.reliability-cohorts button[aria-pressed=true]{border-color:var(--ac-link)}.reliability-cohorts small{display:block;margin-top:6px;font-size:11px;color:var(--ac-muted)}.reliability-ratios{display:grid;grid-template-columns:1fr 1fr auto;gap:24px;padding:20px 0;border-top:1px solid var(--ac-border);align-items:start}.reliability-ratios>div{display:grid;gap:10px;min-width:0}.reliability-ratios span{font-size:13px;display:flex;align-items:center;gap:6px}.reliability-ratios strong{font-size:27px;font-variant-numeric:tabular-nums}.reliability-ratios small{color:var(--ac-muted);font-size:11px;overflow-wrap:anywhere}.reliability-ratios details{font-size:12px;color:var(--ac-muted);max-width:320px}.reliability-dimensions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.reliability-dimensions button{display:grid;gap:13px;border:1px solid var(--ac-border);border-radius:10px;background:var(--ac-surface);color:var(--ac-text);text-align:left;padding:18px;font:inherit;cursor:pointer}.reliability-dimensions button[aria-pressed=true]{border-color:var(--ac-link)}.reliability-dimensions strong{font-size:13px}.reliability-dimensions b{font-size:22px;font-weight:600}.reliability-dimensions span{font-size:11px;color:var(--ac-muted)}.reliability-dimension-detail{margin-top:16px;padding:20px;border:1px solid var(--ac-border);border-radius:10px;background:var(--ac-surface)}.reliability-dimension-detail h3{font-size:15px;margin:0}.reliability-dimension-detail p{font-size:13px;color:var(--ac-muted);line-height:1.8}.reliability-dimension-detail button{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px;width:100%;padding:12px 0;border:0;border-top:1px solid var(--ac-border);background:transparent;color:var(--ac-text);font:inherit;font-size:12px;text-align:left;cursor:pointer}.reliability-dimension-detail button span:last-child{color:var(--ac-link)}.reliability-reply{white-space:pre-wrap;overflow-wrap:anywhere}.reliability-error{color:var(--el-color-danger)}button:focus-visible{outline:2px solid var(--ac-link);outline-offset:3px}
@media(max-width:1100px){.reliability-workspace{grid-template-columns:220px minmax(0,1fr)}.reliability-story{padding:20px}.reliability-ratios{grid-template-columns:1fr 1fr}.reliability-ratios details{grid-column:1/-1;max-width:100%}}
@media(max-width:760px){.reliability-workspace{grid-template-columns:minmax(0,1fr)}.reliability-executions{max-height:250px;border-right:0;border-bottom:1px solid var(--ac-border)}.reliability-executions>button{padding:10px}.reliability-story{padding:18px}.reliability-story>header{display:grid}.reliability-dimensions{grid-template-columns:repeat(2,minmax(0,1fr))}.reliability-dimensions button{padding:14px}.reliability-ratios{gap:18px}.reliability-cohorts button{width:100%}.reliability-business{gap:12px}.reliability-run-facts{gap:8px 12px}.reliability-toolbar{margin-top:18px}.reliability-dimension-detail{padding:16px}}
@media(max-width:370px){.reliability-dimensions{grid-template-columns:minmax(0,1fr)}}
</style>
